    "market": { "type": "string", "description": "Código do país do mercado-alvo (ex: BR, US, PT). Use BR se não mencionado" },
    "lang": { "type": "string", "description": "Idioma-alvo no formato BCP-47 (ex: pt-BR, en-US). Use pt-BR se não mencionado" }
  },
