parameters.jsCode:
const req = $('Parse Request').first()?.json ?? {};
const out = $input.first()?.json ?? {};
const ex  = out.output ?? out;

let url   = typeof ex.url === 'string' ? ex.url.trim() : '';
let topic = typeof ex.topic === 'string' ? ex.topic.trim() : '';
const market = (typeof ex.market === 'string' && ex.market.trim()) ? ex.market.trim().toUpperCase() : 'BR';
const lang   = (typeof ex.lang === 'string' && ex.lang.trim()) ? ex.lang.trim() : 'pt-BR';

let route = 'chat';

if (ex.intent === 'full_analysis') {
  // Completa entidades que o extrator possa ter deixado em branco
  if (!/^https?:\/\//.test(url)) {
    const m = (req.message ?? '').match(/https?:\/\/[^\s,;!?]+/);
    if (m) url = m[0].replace(/[.,;!?]+$/, '');
  }
  if (!topic && url) {
    topic = (req.message ?? '')
      .replace(url, '')
      .replace(/\b(analise|sobre|o site|a url|verifique|quero analisar)\b/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }
  if (/^https?:\/\//.test(url) && topic) route = 'analysis';
} else if (!ex.intent && !req.hasContext) {
  // Fallback heurístico (comportamento V1) caso o extrator de intenção falhe
  const m = (req.message ?? '').match(/https?:\/\/[^\s,;!?]+/);
  const t = m ? (req.message ?? '').replace(m[0], '').replace(/\s+/g, ' ').trim() : '';
  if (m && t.length > 2) {
    url = m[0].replace(/[.,;!?]+$/, '');
    topic = t;
    route = 'analysis';
  }
}

return [{ json: { ...req, route, url, topic, market, lang } }];

const d = $('Definir Rota').first()?.json ?? {};
return [{ json: {
  url: d.url,
  topic: d.topic,
  market: d.market ?? 'BR',
  lang: d.lang ?? 'pt-BR'
} }];

const psi = $input.first()?.json ?? {};
const lhr = psi.lighthouseResult ?? {};
const le  = psi.loadingExperience ?? {};
const aud = lhr.audits ?? {};
const met = le.metrics ?? {};
const scoreRaw = lhr.categories?.performance?.score;
return [{ json: {
  performance_score: scoreRaw != null ? Math.round(scoreRaw * 100) : null,
  fcp:  aud['first-contentful-paint']?.displayValue   ?? null,
  lcp:  aud['largest-contentful-paint']?.displayValue ?? null,
  tbt:  aud['total-blocking-time']?.displayValue      ?? null,
  cls:  aud['cumulative-layout-shift']?.displayValue  ?? null,
  si:   aud['speed-index']?.displayValue              ?? null,
  fcp_field: met.FIRST_CONTENTFUL_PAINT_MS?.category        ?? null,
  lcp_field: met.LARGEST_CONTENTFUL_PAINT_MS?.category      ?? null,
  inp_field: met.INTERACTION_TO_NEXT_PAINT?.category        ?? null,
  cls_field: met.CUMULATIVE_LAYOUT_SHIFT_SCORE?.category    ?? null,
  overall:   le.overall_category ?? null
}}];

const r = $input.first()?.json ?? {};
return [{ json: {
  corepulse_status: r.success ? 'dispatched' : 'failed',
  corepulse_email_enviado: !!r.success,
  corepulse_nota: r.success
    ? 'Relatório CWV detalhado será enviado por e-mail pelo CorePulse Analyzer em alguns minutos.'
    : 'Falha ao acionar o CorePulse: ' + (r.message || JSON.stringify(r).slice(0, 200))
} }];

const fanout    = $('Query Fan-out v2').first()?.json ?? {};
const geo       = $('Prompt Mapper GEO').first()?.json ?? {};
const onPage    = $('On-Page SEO Audit').first()?.json ?? {};
const psi       = $('Parse PSI').first()?.json ?? {};
const corepulse = $('Parse CorePulse').first()?.json ?? {};
const params    = $('Parâmetros de Análise').first()?.json ?? {};

let repertorio = [];
try {
  repertorio = $('Buscar Repertório').all()
    .map(i => i.json)
    .map(r => ({
      trecho: String(r.document?.pageContent ?? r.pageContent ?? '').slice(0, 800),
      fonte: r.document?.metadata?.file_name ?? r.metadata?.file_name ?? null,
      expertise: r.document?.metadata?.expertise ?? r.metadata?.expertise ?? null
    }))
    .filter(r => r.trecho);
} catch (e) {}

let diretrizes = '';
try {
  const lr = $('Carregar Lições (Análise)').all().map(i => i.json).filter(r => r && typeof r.licoes === 'string' && r.licoes.trim());
  if (lr.length) diretrizes = lr[0].licoes.slice(0, 4000);
} catch (e) {}

const context = {
  url_analisada: params.url,
  topico: params.topic,
  mercado: params.market,
  idioma: params.lang,
  diretrizes_aprendidas: diretrizes,
  repertorio_interno: repertorio,
  query_fanout: {
    fanout_queries:   fanout.fanout_queries   ?? {},
    cited_sources:    fanout.cited_sources    ?? {},
    source_diversity: fanout.source_diversity ?? {},
    seo_summary:      fanout.seo_summary      ?? {}
  },
  geo_mapping: {
    summary:       geo.summary ?? '',
    total_prompts: geo.total   ?? 0,
    prompts:       (geo.prompts ?? []).slice(0, 10)
  },
  on_page_audit: onPage,
  cwv_data: {
    psi: {
      fonte: 'PageSpeed Insights API (lab + campo CrUX)',
      performance_score: psi.performance_score,
      metricas_lab: { fcp: psi.fcp, lcp: psi.lcp, tbt: psi.tbt, cls: psi.cls, si: psi.si },
      campo_crux:   { fcp: psi.fcp_field, lcp: psi.lcp_field, inp: psi.inp_field, cls: psi.cls_field, overall: psi.overall }
    },
    corepulse: {
      fonte: 'CorePulse Analyzer (async — relatório detalhado enviado por e-mail, sem métricas inline)',
      status: corepulse.corepulse_status,
      email_enviado: corepulse.corepulse_email_enviado ?? false,
      nota: corepulse.corepulse_nota
    }
  }
};
// meta compacto consumido por "Formatar Análise" via Merge "Anexar Meta".
// Necessário porque Code nodes executados após um AI Agent não podem usar
// $('Nó') — a requisição de dados ao task runner trava até o timeout de 300s.
const meta = {
  url: params.url,
  topico: params.topic,
  mercado: params.market ?? 'BR',
  idioma: params.lang ?? 'pt-BR',
  psi_score:   psi.performance_score ?? null,
  psi_lcp:     psi.lcp     ?? null,
  psi_fcp:     psi.fcp     ?? null,
  psi_cls:     psi.cls     ?? null,
  psi_tbt:     psi.tbt     ?? null,
  psi_overall: psi.overall ?? null,
  corepulse_score: corepulse.corepulse_score ?? null,
  corepulse_lcp:   corepulse.corepulse_lcp   ?? null,
  corepulse_fcp:   corepulse.corepulse_fcp   ?? null,
  corepulse_cls:   corepulse.corepulse_cls   ?? null,
  corepulse_inp:   corepulse.corepulse_inp   ?? null,
  corepulse_tbt:   corepulse.corepulse_tbt   ?? null,
  corepulse_grade: corepulse.corepulse_grade ?? null
};
return [{ json: { correlationContext: JSON.stringify(context, null, 2), meta } }];

