// Sem $('Nó') aqui: Code nodes executados após um AI Agent travam o task
// runner ao requisitar dados de outros nós (timeout de 300s). O contexto
// chega mesclado ao item pelo Merge "Anexar Meta" (campo meta).
const item = $input.first()?.json ?? {};
let analysisData = item.output ?? null;
if (typeof analysisData === 'string') {
  try { analysisData = JSON.parse(analysisData); } catch (e) { analysisData = null; }
}

if (
  !analysisData ||
  typeof analysisData !== 'object' ||
  !analysisData.sumario ||
  !Array.isArray(analysisData.sumario.insights) ||
  analysisData.sumario.insights.length === 0
) {
  analysisData = {
    sumario: {
      insights: ['⚠️ A análise não retornou no formato esperado. Tente novamente em instantes.'],
      nivel_impacto: 'Indeterminado'
    },
    correlacoes: [], gaps_oportunidades: [], plano_acao: [], proximos_passos: []
  };
}

const meta = item.meta ?? {};
const cpHasMetrics =
  meta.corepulse_score != null ||
  meta.corepulse_lcp   != null ||
  meta.corepulse_fcp   != null ||
  meta.corepulse_cls   != null ||
  meta.corepulse_inp   != null;

return [{ json: {
  role: 'assistant', messageType: 'analysis', message: null,
  analysisContext: {
    ...analysisData,
    url_analisada: meta.url,
    topico:        meta.topico,
    mercado:       meta.mercado ?? 'BR',
    idioma:        meta.idioma ?? 'pt-BR',
    psi_score:   meta.psi_score   ?? null,
    psi_lcp:     meta.psi_lcp     ?? null,
    psi_fcp:     meta.psi_fcp     ?? null,
    psi_cls:     meta.psi_cls     ?? null,
    psi_tbt:     meta.psi_tbt     ?? null,
    psi_overall: meta.psi_overall ?? null,
    corepulse_has_metrics: cpHasMetrics,
    corepulse_score:   meta.corepulse_score   ?? null,
    corepulse_lcp:     meta.corepulse_lcp     ?? null,
    corepulse_fcp:     meta.corepulse_fcp     ?? null,
    corepulse_cls:     meta.corepulse_cls     ?? null,
    corepulse_inp:     meta.corepulse_inp     ?? null,
    corepulse_tbt:     meta.corepulse_tbt     ?? null,
    corepulse_grade:   meta.corepulse_grade   ?? null,
    generated_at: new Date().toISOString()
  }
} }];

// Sem $('Nó') aqui: Code nodes executados após um AI Agent travam o task
// runner ao requisitar dados de outros nós (timeout de 300s). Tudo vem da
// linha gravada por "Salvar Resultado"; a mensagem do usuário é preenchida
// por expressão no nó "Registrar Interação" (expressões rodam no processo
// principal e não sofrem desse problema).
const row = $input.first()?.json ?? {};
let p = {};
try {
  p = typeof row.payload === 'string' ? JSON.parse(row.payload) : (row.payload ?? {});
} catch (e) {}

const isAnalysis = p.messageType === 'analysis';
let resposta = '';
if (isAnalysis) {
  resposta = '[análise completa] ' + (p.analysisContext?.url_analisada ?? '') + ' · ' + (p.analysisContext?.topico ?? '');
} else {
  resposta = String(p.message ?? '').slice(0, 4000);
}

return [{ json: {
  jobId: row.jobId ?? '',
  rota: isAnalysis ? 'analysis' : 'chat',
  resposta,
  criado_em: new Date().toISOString()
} }];

const d = $('Definir Rota').first()?.json ?? {};
const message = d.message ?? '';
const history = Array.isArray(d.history) ? d.history : [];
const ctx = d.analysisContext;

// Diretrizes aprendidas (vindas do nó Carregar Lições)
let licoes = '';
try {
  const rows = $('Carregar Lições').all().map(i => i.json).filter(r => r && typeof r.licoes === 'string' && r.licoes.trim());
  if (rows.length) licoes = rows[0].licoes.slice(0, 4000);
} catch (e) {}

let repertorio = '(nenhum repertório interno relevante)';
try {
  const docs = $('Buscar Repertório (Chat)').all().map(i => i.json).map(r => ({
    trecho: String(r.document?.pageContent ?? r.pageContent ?? '').slice(0, 700),
    fonte: r.document?.metadata?.file_name ?? r.metadata?.file_name ?? null,
    expertise: r.document?.metadata?.expertise ?? r.metadata?.expertise ?? null
  })).filter(r => r.trecho);
  if (docs.length) repertorio = docs.map(r => '- [' + (r.expertise || 'n/d') + '] ' + (r.fonte ? '(' + r.fonte + ') ' : '') + r.trecho).join('\n');
} catch (e) {}

const histText = history.length
  ? history.map(m => (m.role === 'user' ? 'Usuário' : 'Assistente') + ': ' + m.content).join('\n\n')
  : '(início da conversa)';

const ctxJSON = ctx ? JSON.stringify({
  url_analisada: ctx.url_analisada,
  topico: ctx.topico,
  mercado: ctx.mercado,
  idioma: ctx.idioma,
  sumario: ctx.sumario,
  correlacoes: ctx.correlacoes,
  gaps_oportunidades: ctx.gaps_oportunidades,
  plano_acao: ctx.plano_acao,
  proximos_passos: ctx.proximos_passos,
  cwv_dados: {
    performance_score: ctx.psi_score,
    lcp: ctx.psi_lcp, fcp: ctx.psi_fcp, cls: ctx.psi_cls, tbt: ctx.psi_tbt,
    campo_geral: ctx.psi_overall
  }
}, null, 2) : '(nenhuma análise completa foi realizada nesta sessão ainda)';

return [{ json: {
  message,
  histText,
  ctxJSON,
  licoes: licoes || '(nenhuma diretriz registrada ainda)',
  repertorio,
  url:    ctx?.url_analisada ?? d.url   ?? '',
  topico: ctx?.topico        ?? d.topic ?? '',
  market: d.market ?? 'BR',
  lang:   d.lang   ?? 'pt-BR'
} }];

