const raw = ($input.first()?.json?.output ?? '').trim();
// Tags de tool-call vazadas pelo modelo. Nomes montados por concatenação para
// evitar corrupção do código por sanitizadores de tags em trânsito.
const TAG_I = 'inv' + 'oke';
const TAG_P = 'para' + 'meter';
const reBlockI = new RegExp('<' + TAG_I + '[\\s\\S]*?<\\/' + TAG_I + '>', 'gi');
const reBlockP = new RegExp('<' + TAG_P + '[\\s\\S]*?<\\/' + TAG_P + '>', 'gi');
const reOrphan = new RegExp('<\\/?(?:' + TAG_I + '|' + TAG_P + ')[^>]*>', 'gi');
const sanitized = raw.replace(reBlockI, '').replace(reBlockP, '').replace(reOrphan, '').trim();
const message = sanitized
  || '⚠️ Não consegui concluir a resposta desta vez (o agente excedeu o limite de iterações ou uma ferramenta falhou). Tente reformular a pergunta ou enviar novamente.';
return [{ json: { role: 'assistant', messageType: 'text', message, analysisContext: null } }];

// Janela de 2 dias: destila apenas sinais recentes (linhas sem criado_em são mantidas)
const corte = new Date(Date.now() - 2 * 24 * 60 * 60 * 1000).toISOString();
const rows = $input.all().map(i => i.json)
  .filter(r => r && r.rating && (!r.criado_em || String(r.criado_em) >= corte));
if (!rows.length) return [];

const fmt = (r) => {
  const origem = r.topico === 'meta-supervisor' ? '[supervisor] ' : '';
  return origem + '[' + (r.rating === 'up' ? 'positivo' : 'negativo') + '] ' +
    'usuário: "' + String(r.mensagem_usuario || '').slice(0, 200) + '" | ' +
    'resposta: "' + String(r.resposta_assistente || '').slice(0, 300) + '"' +
    (r.comentario ? ' | comentário: "' + String(r.comentario).slice(0, 300) + '"' : '');
};

// Contagens refletem só feedback humano; o texto inclui o supervisor rotulado
const userRows = rows.filter(r => r.topico !== 'meta-supervisor');
const positivos = userRows.filter(r => r.rating === 'up').length;
const negativos = userRows.length - positivos;
const feedbackText = rows.slice(0, 100).map(fmt).join('\n');

return [{ json: { total: userRows.length, positivos, negativos, feedbackText } }];

const ag = $('Agregar Feedbacks').first()?.json ?? {};
const lessons = $input.all().map(i => i.json).filter(r => r && typeof r.licoes === 'string' && r.licoes.trim());
return [{ json: {
  ...ag,
  licoesAtuais: lessons.length ? lessons[0].licoes : '(nenhuma diretriz registrada ainda)'
} }];

const out = String($input.first()?.json?.output ?? '').trim();
if (out.length < 20) return [];
return [{ json: { licoes: out.slice(0, 6000) } }];
